package io.aetherdb.examples.social;
import static org.assertj.core.api.Assertions.assertThat;import io.aetherdb.api.typed.*;import io.aetherdb.embedded.typed.AetherEmbedded;import java.time.Instant;import org.junit.jupiter.api.Test;
final class SocialProfileRepositoryTest{
 @Test void profilesAreTypedAtomicQueryableSnapshotAwareAndDeletable(){try(var database=AetherEmbedded.openInMemory()){var repository=new SocialProfileRepository(database);UserProfile original=profile("usr-1","alice",100);assertThat(repository.save(original)).isInstanceOf(TypedWriteResult.Applied.class);try(var snapshot=database.snapshot()){repository.save(profile("usr-1","alice",125));assertThat(repository.at(snapshot).find("usr-1").orElseThrow().followerCount()).isEqualTo(100);assertThat(repository.find("usr-1").orElseThrow().followerCount()).isEqualTo(125);}var result=repository.saveAll(database,profile("usr-3","carol",75),profile("usr-2","bob",50));assertThat(result).isInstanceOfSatisfying(TypedWriteResult.Applied.class,applied->assertThat(applied.operationCount()).isEqualTo(2));assertThat(repository.findAll()).extracting(UserProfile::username).containsExactly("alice","bob","carol");repository.delete("usr-1");assertThat(repository.find("usr-1")).isEmpty();}}
 @Test void codecRoundTripsAndRejectsUnknownVersions(){UserProfile value=profile("usr-1","alice",100);assertThat(UserProfileCodec.INSTANCE.decode(1,UserProfileCodec.INSTANCE.encode(value))).isEqualTo(value);org.junit.jupiter.api.Assertions.assertThrows(IllegalArgumentException.class,()->UserProfileCodec.INSTANCE.decode(2,new byte[0]));}
 private static UserProfile profile(String id,String username,long followers){return new UserProfile(id,username,username.toUpperCase(),username+"@example.test","A useful bio","Zagreb, HR",followers,false,Instant.parse("2025-01-01T00:00:00Z"));}
}
